    TR("pt-nl","Nem pensar!", ["Geen sprake van","Geen sprake van!"], "Expressão fixa.", ["v-geen-sprake-van"]),
    FE(["Daar","ben","ik","het","absoluut","niet","met","eens."], 6, "mee", "daar … mee (não «met»).", ["v-absoluut-niet"]),
