    TR("pt-nl","Desculpa interromper-te.", ["Sorry dat ik je onderbreek","Sorry dat ik jou onderbreek","Excuses dat ik je onderbreek"], "dat + verbo no fim.", ["v-onderbreken"]),
    TR("pt-nl","Posso só dizer uma coisa?", ["Mag ik even iets zeggen","Mag ik even iets zeggen?"], "mag ik even.", ["v-mag-ik-even"]),
    CJ("onderbreken","hij","Hij heeft me drie keer ___.", ["onderbroken"], "Sem ge-: onderbroken.", ["v-onderbreken"], tense="passado-perfeito"),
