    TR("pt-nl","Gosto de variedade.", ["Ik hou van afwisseling","Ik houd van afwisseling"], "houden van.", ["v-afwisseling"]),
    CO("text","Lezersreacties: minder vlees?", "Fenna: «Ik eet al drie jaar vegetarisch, vooral vanwege het dierenwelzijn.»\nRicardo: «Ik eet graag vlees, het is een gewoonte. Maar ik probeer het minder vaak te doen.»\nPiet: «Vleesvervangers zijn vaak duur en sterk bewerkt. Dan eet ik liever bonen of linzen.»\nAnna: «Ik hou van afwisseling: de ene dag vis, de andere dag vegetarisch.»",
       [("Porque é a Fenna vegetariana?", ["*Pelo bem-estar animal","Pela saúde","Pelo preço"]),("Que crítica faz o Piet aos substitutos?", ["*São caros e muito processados","Não têm sabor","São difíceis de encontrar"]),("O que prefere a Anna?", ["*Variedade","Só carne","Só peixe"])],
       "Várias opiniões sobre o mesmo tema.", ["v-vleesvervanger","v-dierenwelzijn","v-gewoonte","v-afwisseling"]),
    FB("Het is moeilijk om een oude ___ te veranderen.", ["gewoonte"], "Hábito.", ["v-gewoonte"], choices=["gewoonte","afwisseling","vleesvervanger"], tr="É difícil mudar um hábito antigo."),
    MC("Qual opinião tem mais nuance?", ["*Ik eet nog vlees, maar minder vaak dan vroeger.","Vlees is slecht, punt.|Absoluto.","Iedereen moet vlees eten.|Absoluto."], "Nuance = matiz.", ["v-mening"]),
    FE(["Ik","eet","liever","bonen","als","vleesvervangers."], 4, "dan", "Comparação: liever … dan.", ["v-vleesvervanger"]),
    LI("Ik probeer minder vaak vlees te eten.", ["Ik probeer minder vaak vlees te eten"], "Tento comer carne menos vezes.", "proberen te + infinitivo.", ["v-gewoonte"]),
    SW("Dê a sua opinião (4 frases) sobre comer menos carne, com um argumento e uma nuance.", ["Ik vind dat we minder vlees moeten eten. Een belangrijk argument is het dierenwelzijn. Toch eet ik zelf nog af en toe vlees, want het is een gewoonte. Ik probeer twee dagen per week vegetarisch te eten."], ["Opinião", "Argumento", "Nuance (toch, maar)"], 35, "Opinião com nuance.", ["v-gewoonte","v-dierenwelzijn"]),
